'use strict';
const KEY='compass-study-v1',days=['월','화','수','목','금'],tabs={today:'☀️ 오늘',table:'🗓️ 시간표',dates:'📝 시험·과제',focus:'⏱️ 집중',review:'💡 복습'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date());
const gap=d=>Math.round((Date.parse(d+'T00:00:00Z')-Date.parse(today()+'T00:00:00Z'))/86400000);
const valid=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d))&&new Date(d).toISOString().slice(0,10)===d;
function restore(raw){const s={table:Array.from({length:5},()=>Array(7).fill('')),bags:Array(5).fill(''),tasks:[],dates:[],reviews:[],timer:{duration:1500,remaining:1500,end:0},sessions:{}};try{const v=JSON.parse(raw);if(!v||typeof v!=='object')return s;for(let i=0;i<5;i++){for(let j=0;j<7;j++)s.table[i][j]=String(v.table?.[i]?.[j]??'').slice(0,40);s.bags[i]=String(v.bags?.[i]??'').slice(0,200)}for(const k of ['tasks','dates','reviews'])if(Array.isArray(v[k]))s[k]=v[k].filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&valid(x.date)).slice(-200).map(x=>({id:x.id.slice(0,80),title:x.title.slice(0,120),date:x.date,done:!!x.done,kind:['시험','과제','수행평가'].includes(x.kind)?x.kind:'과제',subject:String(x.subject||'').slice(0,40),note:String(x.note||'').slice(0,800)}));if([300,600,1500,2400].includes(v.timer?.duration)){s.timer.duration=v.timer.duration;s.timer.remaining=Math.max(0,Math.min(v.timer.duration,Number(v.timer.remaining)||0));s.timer.end=Number.isFinite(v.timer.end)&&v.timer.end>0?v.timer.end:0}if(v.sessions&&typeof v.sessions==='object')for(const [d,n]of Object.entries(v.sessions))if(valid(d)&&Number.isInteger(n)&&n>=0)s.sessions[d]=Math.min(n,100)}catch{}return s}
let state;try{state=restore(localStorage.getItem(KEY))}catch{state=restore(null)}let tab=tabs[location.hash.slice(1)]?location.hash.slice(1):'today',day=Math.min((new Date(today()+'T12:00Z').getUTCDay()+6)%7,4),noticeTimer;
const root=document.querySelector('#content');
function notice(t){const n=document.querySelector('#notice');n.textContent=t;n.style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.style.display='none',4000)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notice('저장 공간을 확인해줘. 지금 기록은 이 화면에 남아 있어.');return false}}
const uid=()=>crypto.randomUUID();
const list=(items,k)=>items.length?items.map(x=>`<div class="row"><input type="checkbox" aria-label="${esc(x.title)} 완료" data-check="${k}" data-id="${esc(x.id)}" ${x.done?'checked':''}><span>${k==='dates'?`<span class="badge">${esc(x.kind)} · ${gap(x.date)===0?'오늘':gap(x.date)>0?'D-'+gap(x.date):Math.abs(gap(x.date))+'일 지남'}</span><br>`:''}<strong>${esc(x.title)}</strong>${k==='tasks'?'':`<small class="muted"> ${esc(x.subject)} · ${esc(x.date)}</small>`}${x.note?`<div class="muted note">${esc(x.note)}</div>`:''}</span>${k==='reviews'?`<button data-task="${esc(x.id)}">오늘 복습</button>`:''}<button class="delete" aria-label="${esc(x.title)} 삭제" data-remove="${k}" data-id="${esc(x.id)}">×</button></div>`).join(''):'<p class="muted">아직 기록이 없어. 작은 것 하나부터 적어볼까?</p>';
function lessons(){const i=(new Date(today()+'T12:00Z').getUTCDay()+6)%7;return i>4?'<p>오늘은 주말이야 🌿 쉬고, 필요하면 복습 하나만!</p>':state.table[i].some(Boolean)?state.table[i].map((x,j)=>`<div class="row"><span>${j+1}교시</span><strong>${esc(x)||'—'}</strong></div>`).join('')+`<p>🎒 ${esc(state.bags[i])||'준비물도 챙겨보자.'}</p>`:'<p class="muted">우리 반 시간표를 먼저 넣어줘.</p><button data-go="table">시간표 입력 →</button>'}
function form(k){if(k==='tasks')return '<form data-form="tasks"><label for="task">오늘 할 일</label><input id="task" name="title" required maxlength="120" placeholder="예: 수학 문제 3개 풀기"><p><button class="primary">추가</button></p></form>';return `<form data-form="${k}">${k==='dates'?'<label for="kind">종류</label><select id="kind" name="kind"><option>시험</option><option>과제</option><option>수행평가</option></select><label for="date">날짜</label><input id="date" name="date" type="date" required value="'+today()+'">':''}<label for="subject">과목</label><input id="subject" name="subject" maxlength="40" placeholder="예: 수학"><label for="title">${k==='reviews'?'다시 생각할 질문':'할 일·시험 이름'}</label><input id="title" name="title" required maxlength="120" placeholder="${k==='reviews'?'어느 부분이 헷갈렸어?':'예: 영어 수행평가'}"><label for="note">${k==='reviews'?'내 설명·다음에 확인할 것':'범위·준비물·메모'}</label><textarea id="note" name="note" maxlength="800"></textarea><p><button class="primary">저장</button></p></form>`}
function render(){document.querySelector('nav').innerHTML=Object.entries(tabs).map(([k,v])=>`<button data-go="${k}" class="${tab===k?'active':''}" aria-current="${tab===k?'page':'false'}">${v}</button>`).join('');if(tab==='today')root.innerHTML=`<div class="grid"><section class="card"><h2>🎒 오늘 수업</h2><p class="muted">${today()}</p>${lessons()}</section><section class="card"><h2>✅ 오늘 할 일</h2>${list(state.tasks.filter(x=>x.date===today()),'tasks')}${form('tasks')}</section></div><section class="card"><h2>📌 이번 주 챙길 것</h2>${list(state.dates.filter(x=>!x.done&&gap(x.date)<=7).sort((a,b)=>a.date.localeCompare(b.date)),'dates')}<button data-go="dates">시험·과제 추가 →</button></section>`;
if(tab==='table')root.innerHTML=`<section class="card"><h2>🗓️ 우리 반 시간표</h2><div class="days">${days.map((d,i)=>`<button data-day="${i}" class="${i===day?'active':''}">${d}</button>`).join('')}</div><p class="muted">입력하면 자동 저장돼. 빈 교시는 비워둬도 좋아.</p>${state.table[day].map((x,j)=>`<div class="lesson"><label for="lesson${j}">${j+1}교시</label><input id="lesson${j}" data-lesson="${j}" maxlength="40" value="${esc(x)}" placeholder="과목 이름"></div>`).join('')}<label for="bag">🎒 ${days[day]}요일 준비물</label><input id="bag" data-bag maxlength="200" value="${esc(state.bags[day])}" placeholder="체육복, 교재 등"></section>`;
if(tab==='dates')root.innerHTML=`<div class="grid"><section class="card"><h2>📝 시험·과제 넣기</h2>${form('dates')}</section><section class="card"><h2>다가오는 일정</h2>${list([...state.dates].sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date)),'dates')}</section></div>`;
if(tab==='review')root.innerHTML=`<div class="grid"><section class="card"><h2>💡 내 말로 다시 설명하기</h2><p class="muted">틀린 이유와 다음에 확인할 것 하나를 적어봐.</p>${form('reviews')}</section><section class="card"><h2>나의 복습 메모</h2>${list([...state.reviews].reverse(),'reviews')}</section></div>`;
if(tab==='focus')root.innerHTML=`<section class="card center"><h2>⏱️ 지금은 한 가지에 집중</h2><p class="muted">끝나면 잠깐 쉬고, 다음 목표를 정해봐.</p><div class="actions">${[600,1500,2400,300].map(n=>`<button data-duration="${n}" ${state.timer.end?'disabled':''} class="${n===state.timer.duration?'active':''}">${n===300?'쉬기 5분':n/60+'분'}</button>`).join('')}</div><div class="clock" id="clock"></div><progress id="progress" max="${state.timer.duration}"></progress><p><button class="primary" data-timer>${state.timer.end?'잠깐 멈추기':'시작 / 이어하기'}</button> <button data-reset>처음부터</button></p><p class="muted">오늘 마친 집중 타이머: ${state.sessions[today()]||0}회</p><p>🐾 조금씩 해도 괜찮아. 지금 시작한 네가 멋져!</p></section>`;tick()}
function tick(){const t=state.timer;if(t.end){t.remaining=Math.max(0,Math.ceil((t.end-Date.now())/1000));if(!t.remaining){t.end=0;if(t.duration!==300)state.sessions[today()]=(state.sessions[today()]||0)+1;save();notice(t.duration===300?'쉬는 시간 끝! 다음 한 가지를 골라봐.':'집중 시간 끝! 잠깐 쉬어가자 🌱');render();return}}const c=document.querySelector('#clock');if(c)c.textContent=String(Math.floor(t.remaining/60)).padStart(2,'0')+':'+String(t.remaining%60).padStart(2,'0');const p=document.querySelector('#progress');if(p)p.value=t.duration-t.remaining}
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-lesson')){state.table[day][Number(e.target.dataset.lesson)]=e.target.value;save()}if(e.target.hasAttribute('data-bag')){state.bags[day]=e.target.value;save()}});
document.addEventListener('change',e=>{const k=e.target.dataset.check;if(k){const x=state[k].find(x=>x.id===e.target.dataset.id);if(x){x.done=e.target.checked;save()}}});
document.addEventListener('submit',e=>{const k=e.target.dataset.form;if(!k)return;e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')||'').trim(),date=k==='dates'?String(f.get('date')):today();if(!title||!valid(date))return;if(state[k].length>=200){notice('기록이 200개야. 지난 기록을 정리한 뒤 추가해줘.');return}state[k].push({id:uid(),title,date,done:false,kind:String(f.get('kind')||'과제'),subject:String(f.get('subject')||''),note:String(f.get('note')||'')});if(save()){render();notice('저장했어! 하나씩 해보자 🐾')}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){tab=b.dataset.go;if(location.hash==='#'+tab)render();else location.hash=tab}if(b.dataset.day){day=Number(b.dataset.day);render()}if(b.dataset.remove){state[b.dataset.remove]=state[b.dataset.remove].filter(x=>x.id!==b.dataset.id);save();render();notice('기록을 지웠어.')}if(b.dataset.task){const x=state.reviews.find(x=>x.id===b.dataset.task);if(x&&!state.tasks.some(t=>t.date===today()&&t.title===x.title)&&state.tasks.length<200){state.tasks.push({id:uid(),title:x.title,date:today(),done:false});save();notice('오늘 할 일에 넣었어.')}}if(b.dataset.duration){state.timer={duration:Number(b.dataset.duration),remaining:Number(b.dataset.duration),end:0};save();render()}if(b.hasAttribute('data-timer')){tick();const t=state.timer;if(t.end)t.end=0;else{if(t.remaining===0)t.remaining=t.duration;t.end=Date.now()+t.remaining*1000}save();render()}if(b.hasAttribute('data-reset')){state.timer.remaining=state.timer.duration;state.timer.end=0;save();render()}});
window.addEventListener('hashchange',()=>{if(tabs[location.hash.slice(1)]){tab=location.hash.slice(1);render()}});render();setInterval(tick,1000);

